const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    try {
        // 1. Geometry & Time Definitions
        const analysisDate = '2024-11-08';
        const startDate = ee.Date(analysisDate);
        const endDate = startDate.advance(1, 'day');

        // Load administrative boundaries for Indian states
        const adminBoundaries = ee.FeatureCollection('FAO/GAUL/2015/level1');
        const punjabGeometry = adminBoundaries.filter(ee.Filter.eq('ADM1_NAME', 'Punjab')).geometry();
        const haryanaGeometry = adminBoundaries.filter(ee.Filter.eq('ADM1_NAME', 'Haryana')).geometry();

        // 2. Data Acquisition & Check
        const firmsCollection = ee.ImageCollection('FIRMS')
            .filterDate(startDate, endDate);

        // Check if data is available for the specified day
        const collectionSize = firmsCollection.size().getInfo();
        if (collectionSize === 0) {
            console.log(`No FIRMS data found for ${analysisDate}.`);
            console.log('A: No');
            return;
        }

        // Create a single image mosaic for the day and select the confidence band
        const firmsImage = firmsCollection.select('confidence').mosaic();

        // 3. Processing: Count high-confidence fire pixels
        // A confidence value >= 80 represents nominal and high-confidence fire detections.
        const highConfidenceFires = firmsImage.gte(80);

        // Count pixels in Punjab
        const punjabStats = highConfidenceFires.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: punjabGeometry,
            scale: 1000,
            maxPixels: 1e9
        });

        // Count pixels in Haryana
        const haryanaStats = highConfidenceFires.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: haryanaGeometry,
            scale: 1000,
            maxPixels: 1e9
        });

        // 4. Calculation
        // .get() can return null if the region is empty or outside the image footprint.
        // We use .get('confidence') as that's the band we selected and processed.
        // The .sum() reducer on a binary mask (0s and 1s) gives the count of '1' pixels.
        const punjabFireCount = ee.Number(punjabStats.get('confidence')).getInfo();
        const haryanaFireCount = ee.Number(haryanaStats.get('confidence')).getInfo();

        // 5. Validation & Final Answer
        if (punjabFireCount === null || haryanaFireCount === null) {
            console.log("Calculation failed: Could not retrieve fire counts for one or both regions.");
            console.log("Punjab Count:", punjabFireCount);
            console.log("Haryana Count:", haryanaFireCount);
            console.log('C3');
            return;
        }

        console.log(`Date: ${analysisDate}`);
        console.log(`Punjab high-confidence fire pixels: ${punjabFireCount}`);
        console.log(`Haryana high-confidence fire pixels: ${haryanaFireCount}`);

        if (punjabFireCount === 0 && haryanaFireCount === 0) {
            console.log("No high-confidence fires were detected in either state.");
        }

        if (punjabFireCount > haryanaFireCount) {
            console.log('A');
        } else {
            console.log('B');
        }

    } catch (error) {
        console.error("An error occurred during the analysis:", error);
        console.log('D');
    }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log('D');
  }
}

initEE();
